from importlib import import_module
v=import_module("labs.propriedades-organicas.vapor")
t=v.boiling_temperature("dimethyl_ether",.9)
assert abs(v.vapor_pressure("dimethyl_ether",t)-.9)<1e-10
try:
    v.boiling_temperature("dimethyl_ether",1.01325)
except ValueError:
    pass
else:
    raise AssertionError("O ajuste foi usado fora da faixa")
